def find_seps(g):
    h,w=len(g),len(g[0])
    sep_rows=[r for r in range(h) if len(set(g[r]))==1]
    sep_cols=[c for c in range(w) if len(set(g[r][c] for r in range(h)))==1]
    return sep_rows,sep_cols

def tiled_output(g):
    h,w=len(g),len(g[0])
    sr,sc=find_seps(g)
    # panel row blocks
    rb=[r for r in range(h) if r not in sr]
    cb=[c for c in range(w) if c not in sc]
    # contiguous blocks
    def blocks(idx):
        out=[];cur=[idx[0]]
        for x in idx[1:]:
            if x==cur[-1]+1: cur.append(x)
            else: out.append(cur);cur=[x]
        out.append(cur);return out
    rb=blocks(rb); cb=blocks(cb)
    # find source panel: panel with cells differing from its own dominant color
    src=None
    for bi,rbk in enumerate(rb):
        for bj,cbk in enumerate(cb):
            cells=[g[r][c] for r in rbk for c in cbk]
            dom=Counter(cells).most_common(1)[0][0]
            if any(v!=dom for v in cells):
                src=(bi,bj,dom)
    if src is None: return None
    bi,bj,dom=src
    pat={(r-rb[bi][0],c-cb[bj][0]):g[r][c] for r in rb[bi] for c in cb[bj] if g[r][c]!=dom}
    out=[row[:] for row in g]
    for rbk in rb:
        for cbk in cb:
            for dr,dv in pat.items():
                out[rbk[dr]][cbk[dv]]=pat[(dr,dv)]
    return out

